import numpy as np

def idx(r,c,ch): return (r*10+c)*5+ch

def state(agent, prev, objs=()):
    x = np.zeros(500)
    x[idx(agent[0],agent[1],0)] = 1
    x[idx(prev[0],prev[1],4)] = 1
    for (r,c,ch) in objs:
        x[idx(r,c,ch)] = 1
        if ch == 1:                 # moving object was there last step too
            x[idx(r,c,4)] = 1
    return x

